      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha d_a70f para determinar se a mudança afeta o marco e em que magnitude."
    ],
    "motivo": "Sem a relação entre a atividade afetada e o marco, não se pode estabelecer a variação do término.",
    "unidade": "dia_corrido"
  },
