      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O custo do apoio depende do término de liberar estação, que não pode ser determinado sem as precedências da ficha d_a70f."
    ],
    "motivo": "As parcelas fixas são conhecidas, mas o valor do apoio depende do prazo final e não há suporte para calculá-lo após o aviso.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
